// Config — настройки. Меняйте значения справа от двоеточия.
return [{ json: {
  "timezone": "Europe/Kyiv",
  "locale": "ru-RU",
  "sheets_api_base": "https://sheets.googleapis.com/v4",
  "spreadsheet_id": "REPLACE_WITH_SPREADSHEET_ID",
  "plan_sheet": "Plan",
  "approval_chat_id": "REPLACE_WITH_APPROVAL_CHAT_ID"
} }];

// Act on Draft — buttons and replies in the approval chat: publish, rewrite, skip, or replace the text.
const cfg = $('Config').first().json;
// ---- shared helpers ----
const MIN = 60000;
const nowMs = () => (cfg.now_override ? Date.parse(cfg.now_override) : Date.now());
const digitsOf = (value) => String(value || '').replace(/[^\d]/g, '');
// Phones are stored in one international form, so the same person is recognised however they typed it.
function phoneOf(value) {
  const rules = cfg.phone || {};
  let d = digitsOf(value);
  if (d.startsWith('00')) d = d.slice(2);
  else if (rules.national_prefix && rules.country_code && d.startsWith(rules.national_prefix) && !d.startsWith(rules.country_code)) {
    d = rules.country_code + d.slice(rules.national_prefix.length);
  }
  return d.length >= 9 && d.length <= 15 ? '+' + d : '';
}
function emailOf(value) {
  const e = String(value || '').trim().toLowerCase();
  return /^[^\s@<>()",;]+@[^\s@<>()",;]+\.[a-z]{2,}$/.test(e) ? e : '';
}
const localText = (ms) => new Intl.DateTimeFormat(cfg.locale || 'ru-RU', {
  timeZone: cfg.timezone, day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit',
}).format(new Date(ms));
function localParts(ms) {
  const parts = {};
  for (const p of new Intl.DateTimeFormat('en-GB', { timeZone: cfg.timezone, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', weekday: 'short' }).formatToParts(new Date(ms))) parts[p.type] = p.value;
  return { date: `${parts.year}-${parts.month}-${parts.day}`, hour: Number(parts.hour), minute: Number(parts.minute), weekday: parts.weekday.toLowerCase().slice(0, 3) };
}
const sheetUrl = (path) => `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values/${path}`;
const quoteSheet = (name) => "'" + String(name).replace(/'/g, "''") + "'";
// Plan sheet: one row per post. Columns A–G are the team's; H–Q are kept by the workflows (notes holds the editor's rewrite request).
const PCOLS = ['id', 'publish_at', 'channel', 'topic', 'brief', 'pillar', 'image_url', 'status', 'title', 'draft', 'final', 'attempts', 'approved_by',
  'published_at', 'link', 'error', 'notes'];
const BOT_FROM = PCOLS.indexOf('status');
const BOT_TO = PCOLS.indexOf('notes');
const colLetter = (index) => String.fromCharCode(65 + index);
const planRange = () => `${quoteSheet(cfg.plan_sheet)}!A1:${colLetter(PCOLS.length - 1)}`;
// Unformatted values: dates come back as serial numbers whatever the spreadsheet's locale is.
const planReadUrl = () => sheetUrl(encodeURIComponent(planRange())) + '?valueRenderOption=UNFORMATTED_VALUE&dateTimeRenderOption=SERIAL_NUMBER';
function planTable(values) {
  const all = values || [];
  const header = all.length > 0 && String(all[0][0]).trim().toLowerCase() === 'id';
  return { header, rows: (header ? all.slice(1) : all).map((r, i) => ({ sheetRow: i + (header ? 2 : 1), post: planObject(r) })) };
}
function planObject(row) {
  const o = {};
  PCOLS.forEach((c, i) => { const v = row[i]; o[c] = v === undefined || v === null ? '' : (c === 'publish_at' && typeof v === 'number' ? v : String(v).trim()); });
  o.status = o.status.toLowerCase() || (o.topic ? 'idea' : '');
  o.attempts = Number(o.attempts) || 0;
  return o;
}
// The workflows write H–Q in one range, so the team's columns are never touched.
function botWrite(sheetRow, post) {
  return { range: `${quoteSheet(cfg.plan_sheet)}!${colLetter(BOT_FROM)}${sheetRow}:${colLetter(BOT_TO)}${sheetRow}`, values: [PCOLS.slice(BOT_FROM, BOT_TO + 1).map((c) => String(post[c] === undefined ? '' : post[c]))] };
}
const batchUpdate = (data) => ({ method: 'POST', url: `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values:batchUpdate`, body: { valueInputOption: 'RAW', data } });
function localToMs(y, mo, d, h, mi) {
  const want = Date.UTC(y, mo - 1, d, h, mi);
  let guess = want;
  for (let i = 0; i < 3; i++) {
    const p = localParts(guess);
    guess += want - Date.UTC(Number(p.date.slice(0, 4)), Number(p.date.slice(5, 7)) - 1, Number(p.date.slice(8, 10)), p.hour, p.minute);
  }
  return guess;
}
// publish_at: a date cell (serial number), "2026-10-28 10:00" or "28.10.2026 10:00", in the Config time zone. Empty means "as soon as possible".
function whenOf(value) {
  if (value === '' || value === null || value === undefined) return null;
  if (typeof value === 'number' || /^\d+(\.\d+)?$/.test(String(value))) {
    const wall = new Date(Math.round((Number(value) - 25569) * 86400000));
    return localToMs(wall.getUTCFullYear(), wall.getUTCMonth() + 1, wall.getUTCDate(), wall.getUTCHours(), wall.getUTCMinutes());
  }
  const s = String(value).trim();
  let m = /^(\d{4})-(\d{1,2})-(\d{1,2})(?:[ T](\d{1,2}):(\d{2}))?/.exec(s);
  if (m) return localToMs(+m[1], +m[2], +m[3], +(m[4] || 9), +(m[5] || 0));
  m = /^(\d{1,2})[./](\d{1,2})[./](\d{4})(?:,?\s+(\d{1,2}):(\d{2}))?/.exec(s);
  if (m) return localToMs(+m[3], +m[2], +m[1], +(m[4] || 9), +(m[5] || 0));
  return NaN;
}
const pad = (n) => String(n).padStart(2, '0');
const stamp = (ms) => { const p = localParts(ms); return `${p.date} ${pad(p.hour)}:${pad(p.minute)}`; };
function parseModelJson(input) {
  const content = input && input.choices && input.choices[0] && input.choices[0].message && input.choices[0].message.content;
  if (!content) return { problem: input && input.error ? 'llm_error' : 'no_answer' };
  try { const t = String(content).replace(/```(json)?/g, ''); return { data: JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1)) }; } catch (e) { return { problem: 'bad_json' }; }
}
const llmBase = (messages) => ({ model: (cfg.llm || {}).model, temperature: (cfg.llm || {}).temperature === undefined ? 0.7 : cfg.llm.temperature,
  ...((cfg.llm || {}).json_mode ? { response_format: { type: 'json_object' } } : {}), messages });
function brandLines() {
  const b = cfg.brand || {};
  return [`Бренд: ${b.name || ''}. ${b.about || ''}`, `Аудитория: ${b.audience || ''}`, `Голос: ${b.voice || ''}`,
    ...(b.rules || []).map((r) => `- ${r}`)].join('\n');
}
const update = $('Telegram Trigger').first().json;
const table = planTable($input.first().json.values);
const chat = String(cfg.approval_chat_id);
const out = (json) => [{ json: Object.assign({ act: false, write: false, note: '', callback_id: '', chat: cfg.approval_chat_id }, json) }];
let action = '', id = '', text = '', who = '', callbackId = '';
const cb = update.callback_query;
if (cb) {
  if (String(cb.message && cb.message.chat && cb.message.chat.id) !== chat) return out({});
  [action, id] = String(cb.data || '').split(/:(.*)/s);
  who = [cb.from.first_name, cb.from.last_name].filter(Boolean).join(' ') || cb.from.username || '';
  callbackId = cb.id;
} else if (update.message && String(update.message.chat.id) === chat && update.message.text) {
  const ref = /ID: (\S+)\s*$/.exec((update.message.reply_to_message || {}).text || '');
  if (!ref) return out({});
  id = ref[1];
  text = update.message.text.trim();
  const rewrite = /^(переписать|переделать|rewrite)\s*[:\-—]\s*/i.exec(text);
  action = rewrite ? 'redo' : 'edit';
  if (rewrite) text = text.slice(rewrite[0].length);
  who = [update.message.from.first_name, update.message.from.last_name].filter(Boolean).join(' ');
} else return out({});
if (!['ok', 'redo', 'skip', 'edit'].includes(action) || !id) return out({});
const found = table.rows.find(({ post }) => post.id === id);
if (!found) return out({ act: true, callback_id: callbackId, note: `Публикация ${id} не найдена в таблице` });
const post = Object.assign({}, found.post);
if (['published', 'publishing', 'skipped'].includes(post.status)) return out({ act: true, callback_id: callbackId, note: `«${post.topic}» уже ${post.status === 'skipped' ? 'пропущена' : 'опубликована'}` });
const write = (note) => out({ act: true, write: true, callback_id: callbackId, note, http: batchUpdate([botWrite(found.sheetRow, post)]) });
const at = whenOf(post.publish_at);
const when = at ? `в ${stamp(at)}` : 'в ближайшие минуты';
if (action === 'ok') {
  if (!post.draft && !post.final) return out({ act: true, callback_id: callbackId, note: 'Черновика ещё нет' });
  post.status = 'approved'; post.final = post.final || post.draft; post.approved_by = who;
  return write(`${who || 'Команда'} одобрил(а) «${post.topic}». Публикация ${when}.`);
}
if (action === 'edit') {
  post.status = 'approved'; post.final = text.slice(0, 20000); post.approved_by = who;
  return write(`Текст «${post.topic}» заменён и одобрен (${who}). Публикация ${when}.`);
}
if (action === 'redo') {
  post.status = 'idea'; post.attempts = 0; post.error = '';
  post.notes = text ? text.slice(0, 1000) : post.notes;
  return write(`«${post.topic}» — пишу новый вариант${text ? ' с учётом замечания' : ''}.`);
}
post.status = 'skipped';
return write(`«${post.topic}» пропущена.`);
